import React from 'react';

import clsx from 'clsx';
export const ProgressType = {};

interface IPohProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  value: number;
  containerClassName?: string;
  striped?: boolean;
  animated?: boolean;
}

const PohProgress: React.FC<IPohProgressProps> = ({
  value,
  children,
  striped = false,
  animated = false,
  className,
  containerClassName,
  ...otherProps
}) => (
  <div className={clsx('progress', containerClassName)} {...otherProps}>
    <div
      className={clsx(
        'progress-bar',
        { 'progress-bar-striped': striped, 'progress-bar-animated': animated },
        className,
      )}
      role="progressbar"
      style={{ width: `${value}%` }}
      aria-valuenow={value}
      aria-valuemin={0}
      aria-valuemax={100}
    >
      {children}
    </div>
  </div>
);

export default PohProgress;
